private static int decodeOctets(int i,ByteBuffer bb,StringBuilder sb){
    while (bb.hasRemaining()){
        byte b = bb.get();
        if (b >= 0){
            sb.append((char) b);
        } else {
            // Handle multi-byte UTF-8 characters
            int count = 0;
            if ((b & 0xF0) == 0xE0){
                count = 2;
            } else if ((b & 0xF8) == 0xF0){
                count = 3;
            } else if ((b & 0xFC) == 0xF8){
                count = 4;
            } else if ((b & 0xFE) == 0xFC){
                count = 5;
            } else {
                // Invalid UTF-8 start byte
                continue;
            }
            char[] cbuf = new char[count];
            for (int j = 0; j < count; j++){
                b = bb.get();
                cbuf[j] = (char) ((b & 0x3F) << (6 * (count - j - 1)));
            }
            sb.append(new String(cbuf));
        }
    }
    return i;
}

