public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder out = new StringBuilder();
    int escapecode = 0;

    int pos = 0;
    int len = str.length();
    while (pos < len) {
        char ch = str.charAt(pos);

        if (ch == '\\') {
            if (++pos == len) {
                out.append('\\');
                break;
            }
            ch = str.charAt(pos);

            switch (ch) {
                case 'b':
                    out.append('\b');
                    break;
                case 't':
                    out.append('\t');
                    break;
                case 'n':
                    out.append('\n');
                    break;
                case 'f':
                    out.append('\f');
                    break;
                case 'r':
                    out.append('\r');
                    break;
                case 'u':
                    escapecode = 0;
                    for (int i = 0; i < 4; i++) {
                        int hex = Character.digit(str.charAt(++pos), 16);
                        if (hex < 0 || hex > 15) {
                            throw new NumberFormatException("Malformed Unicode escape sequence \\u" + str.substring(pos - 4));
                        }
                        escapecode = (escapecode << 4) | hex;
                    }
                    out.append((char) escapecode);
                    break;
                default:
                    if (isHexDigit(ch)) {
                        if (++pos < len && isHexDigit(str.charAt(pos))) {
                            out.append((char) Integer.parseInt("" + ch + str.charAt(pos), 16));
                            ++pos;
                        } else {
                            out.append('\\').append(ch);
                        }
                    } else {
                        out.append('\\').append(ch);
                    }
                    break;
            }
        } else {
            out.append(ch);
        }
        pos++;
    }
    return out.toString();
}

